function canWinPile(n: number): boolean {
  // a, b, c = win[i-3], win[i-2], win[i-1]; win[0] is false, negative sizes are treated as won (not reachable)
  let a = true, b = true, c = false;
  for (let i = 1; i <= n; i++) {
    const cur = !a || !b || !c;
    a = b; b = c; c = cur;
  }
  return c;
}

