class Solution:
    def canWinPile(self, n: int) -> bool:
        # a, b, c = win[i-3], win[i-2], win[i-1]
        a, b, c = True, True, False
        for _ in range(n):
            a, b, c = b, c, (not a) or (not b) or (not c)
        return c

